import Foundation
import XCTest
@testable import MinikTripleShot

// Parity tests for area s-one1 (spec 15-one1): TripleShotOneOnOneFragment.kt lines 1-1794 and both layouts.
//
// Golden vectors come from the snapshot's own Kotlin (dd722e5): the model files compiled unchanged plus verbatim
// copies of the fragment's formula members, run on the JVM with kotlin-stdlib 2.3.21
// (work/s-one1/harness/src/OneOnOneHarness.kt, output golden.txt). They reproduce every table of spec 15 section 7.4.
// Covered here: chanceDrivenSkill (seeded make/miss -> release errors, exact Float bits, every zone and finish,
// clamped chances, wrapping seed products), shouldBotBiteOnCurrentGather (5 character pairs, 3 seeds, 5 shot
// sequences, every fake history up to 3 entries), recordHumanShotDecision (3-entry window, Java List hashCode),
// baseShotChance (every roster profile, zone and finish), currentRecentMovementIntensity (300 ms hold, 620 ms decay,
// fake clock) and the view trees of res/layout and res/layout-land (ids, classes, visibility, px sizes, margins,
// text sizes, constraints) plus the iOS-only exit control.
// Not covered (they read the live court: shot contest, zone, defender geometry): calculateHumanShotChance,
// calculateBotShotChance, shouldBotJumpOnRealShot and the meter pose pull; the harness checks their formulas against
// spec 15 section 7.4 (HUMAN / BOTPCT / JUMP / POSE lines of golden.txt).

final class OneOnOnePart1Tests: XCTestCase {

    private static let HUMAN_SHOT_ROLL_SALT: Int64 = 0x53484F5448554D41
    private static let BOT_SHOT_ROLL_SALT: Int64 = 0x53484F54424F5453

    override func tearDown() {
        AFakeClock.uninstall()
        super.tearDown()
    }

    private func makeFragment(seed: Int64 = 31337,
                              human: String = TripleShotCharacterRoster.ID_WOMAN_DARK,
                              bot: String = "nova") -> TripleShotOneOnOneFragment {
        let fragment = TripleShotOneOnOneFragment()
        fragment.seed = seed
        fragment.humanProfile = TripleShotCharacterRoster.find(id: human)!
        fragment.botProfile = TripleShotCharacterRoster.find(id: bot)!
        return fragment
    }

    private func bits(_ hex: String) -> UInt32 {
        return UInt32(hex.dropFirst(2), radix: 16)!
    }

    private func lines(_ data: String) -> [[String]] {
        return data.split(separator: "\n").map { $0.split(separator: " ").map(String.init) }
    }

    private func zone(_ s: String) -> ShotZone { return ShotZone.named(s)! }

    private func finish(_ s: String) -> TripleShotCourtView.OneOnOneDriveFinish {
        return TripleShotCourtView.OneOnOneDriveFinish.named(s)!
    }

    private func history(_ s: String) -> [Bool] {
        if s == "-" { return [] }
        return s.split(separator: ",").map { $0 == "t" }
    }

    // MARK: chanceDrivenSkill

    /// Spec 15 section 7.4, `chanceDrivenSkill` table (seed 31337).
    func testChanceDrivenSkillSpecTable() {
        let fragment = makeFragment()
        let base = ShotSkill(aimError: 0.5, powerError: -0.25, arcError: 0.125, rawPeakGyro: 3, rawReleasePitchDeg: 4)
        let human = OneOnOnePart1Tests.HUMAN_SHOT_ROLL_SALT
        let bot = OneOnOnePart1Tests.BOT_SHOT_ROLL_SALT
        typealias Row = (Int64, Int64, Int, ShotZone, TripleShotCourtView.OneOnOneDriveFinish, String?, String?)
        let rows: [Row] = [
            (1, human, 70, .THREE_POINT, .JUMPER, "0.76668835", "0.010534501"),
            (1, human, 70, .MID_RANGE, .JUMPER, "0.7363096", "0.01520575"),
            (1, human, 82, .INSIDE, .JUMPER, nil, nil),
            (1, human, 40, .THREE_POINT, .JUMPER, "-0.34", "-0.06636059"),
            (1, human, 8, .THREE_POINT, .JUMPER, "-0.7563252", "0.008017942"),
            (2, human, 70, .THREE_POINT, .JUMPER, "0.34", "-0.06719914"),
            (4, human, 90, .INSIDE, .DUNK, "-0.7372532", "0.017974868"),
            (1, bot, 70, .THREE_POINT, .JUMPER, nil, nil),
            (1, bot, 40, .THREE_POINT, .JUMPER, "-0.8958305", "0.013113344"),
            (3, bot, 40, .THREE_POINT, .JUMPER, "-0.34", "0.07754272"),
        ]
        for (sequence, salt, chance, zone, finish, aim, power) in rows {
            let skill = fragment.chanceDrivenSkill(baseSkill: base, chancePercent: chance, sequence: sequence,
                                                   salt: salt, zone: zone, finish: finish)
            let label = "seq \(sequence) chance \(chance) \(zone) \(finish)"
            XCTAssertEqual(skill.aimError.bitPattern, (aim.map { Float($0)! } ?? 0).bitPattern, label)
            XCTAssertEqual(skill.powerError.bitPattern, (power.map { Float($0)! } ?? 0).bitPattern, label)
            XCTAssertEqual(skill.arcError.bitPattern, Float(0).bitPattern, label)
            XCTAssertEqual(skill.rawPeakGyro.bitPattern, Float(0).bitPattern, label)
            XCTAssertEqual(skill.rawReleasePitchDeg.bitPattern, Float(0).bitPattern, label)
        }
    }

    /// JVM sweep: 6 seeds (incl. 0, negative, Long.MAX_VALUE), both salts, sequences up to Long.MAX_VALUE (wrapping
    /// products), chances 3..120 (clamped to 8..95), every zone and finish.
    func testChanceDrivenSkillJvmSweep() {
        let base = ShotSkill(aimError: 0.5, powerError: -0.25, arcError: 0.125, rawPeakGyro: 3, rawReleasePitchDeg: 4)
        var fragments: [Int64: TripleShotOneOnOneFragment] = [:]
        var checked = 0
        for f in lines(OneOnOnePart1Tests.chanceDrivenSkillData) {
            // CDS seed salt sequence chance zone finish aimBits powerBits arcBits gyroBits pitchBits
            let seed = Int64(f[1])!
            let fragment = fragments[seed] ?? makeFragment(seed: seed)
            fragments[seed] = fragment
            let salt = f[2] == "HUMAN" ? OneOnOnePart1Tests.HUMAN_SHOT_ROLL_SALT : OneOnOnePart1Tests.BOT_SHOT_ROLL_SALT
            let skill = fragment.chanceDrivenSkill(baseSkill: base, chancePercent: Int(f[4])!, sequence: Int64(f[3])!,
                                                   salt: salt, zone: zone(f[5]), finish: finish(f[6]))
            let label = f.joined(separator: " ")
            XCTAssertEqual(skill.aimError.bitPattern, bits(f[7]), label)
            XCTAssertEqual(skill.powerError.bitPattern, bits(f[8]), label)
            XCTAssertEqual(skill.arcError.bitPattern, bits(f[9]), label)
            XCTAssertEqual(skill.rawPeakGyro.bitPattern, bits(f[10]), label)
            XCTAssertEqual(skill.rawReleasePitchDeg.bitPattern, bits(f[11]), label)
            checked += 1
        }
        XCTAssertEqual(checked, 2700)
    }

    // MARK: Bot pump-fake read

    /// Spec 15 section 7.4 bite table: Maya vs Mia Essence Skies, seed 31337.
    func testBotBiteSpecTable() {
        let rows: [(Int64, [Bool], Bool)] = [
            (0, [], true), (0, [true], true), (0, [false], true), (0, [true, true], false),
            (0, [true, false, true], false), (0, [true, true, true], false), (1, [], false),
            (1, [true, true, true], true), (2, [], true),
        ]
        for (sequence, fakes, expected) in rows {
            let fragment = makeFragment()
            fragment.shotSequence = sequence
            fragment.recentHumanShotFakes = fakes
            XCTAssertEqual(fragment.shouldBotBiteOnCurrentGather(), expected, "seq \(sequence) \(fakes)")
            // The read neither records nor advances anything.
            XCTAssertEqual(fragment.recentHumanShotFakes, fakes)
            XCTAssertEqual(fragment.shotSequence, sequence)
        }
    }

    func testBotBiteJvmSweep() {
        var checked = 0
        for f in lines(OneOnOnePart1Tests.biteData) {
            // BITE human bot seed shotSequence history expected
            let fragment = makeFragment(seed: Int64(f[3])!, human: f[1], bot: f[2])
            fragment.shotSequence = Int64(f[4])!
            fragment.recentHumanShotFakes = history(f[5])
            XCTAssertEqual(fragment.shouldBotBiteOnCurrentGather(), f[6] == "true", f.joined(separator: " "))
            checked += 1
        }
        XCTAssertEqual(checked, 1125)
    }

    // MARK: Fake history

    func testRecordHumanShotDecisionKeepsTheLastThree() {
        let fragment = makeFragment()
        let decisions = [true, false, true, true, false, false, true]
        let expected = lines(OneOnOnePart1Tests.historyData)
        XCTAssertEqual(expected.count, decisions.count)
        for (i, fake) in decisions.enumerated() {
            fragment.recordHumanShotDecision(fake: fake)
            XCTAssertEqual(fragment.recentHumanShotFakes, history(expected[i][1]), "after \(i + 1)")
            XCTAssertEqual(Int(fragment.recentHumanShotFakes.javaHashCode), Int(expected[i][2])!, "after \(i + 1)")
        }
    }

    // MARK: Base chance

    func testBaseShotChanceForEveryProfile() {
        let fragment = makeFragment()
        var checked = 0
        for f in lines(OneOnOnePart1Tests.baseData) {
            // BASE profileId zone finish bits
            let profile = TripleShotCharacterRoster.find(id: f[1])!
            let value = fragment.baseShotChance(profile: profile, zone: zone(f[2]), finish: finish(f[3]))
            XCTAssertEqual(value.bitPattern, bits(f[4]), f.joined(separator: " "))
            checked += 1
        }
        XCTAssertEqual(checked, 108)
        XCTAssertEqual(checked, TripleShotCharacterRoster.all.count * 9)
    }

    /// Spec 15 section 7.4 roster table: settled open base % (Float32 truncation).
    func testSettledOpenBasePercentMaya() {
        let fragment = makeFragment()
        let maya = TripleShotCharacterRoster.womanDark
        XCTAssertEqual(fragment.baseShotChance(profile: maya, zone: .INSIDE, finish: .JUMPER).toInt(), 82)
        XCTAssertEqual(fragment.baseShotChance(profile: maya, zone: .MID_RANGE, finish: .JUMPER).toInt(), 76)
        XCTAssertEqual(fragment.baseShotChance(profile: maya, zone: .THREE_POINT, finish: .JUMPER).toInt(), 70)
        XCTAssertEqual(fragment.baseShotChance(profile: maya, zone: .THREE_POINT, finish: .LAYUP).toInt(), 86)
        XCTAssertEqual(fragment.baseShotChance(profile: maya, zone: .INSIDE, finish: .DUNK).toInt(), 90)
    }

    // MARK: Momentum

    func testRecentMovementIntensityHoldsThenDecays() {
        let now: Int64 = 5_000_000_000_000
        AFakeClock.install(nanos: now)
        let fragment = makeFragment()
        fragment.recentMoveIntensity01 = 0.83
        for f in lines(OneOnOnePart1Tests.momentumData) {
            // MOM ageMs bits | MOM unset bits
            if f[1] == "unset" {
                fragment.recentMoveAtNanos = 0
            } else {
                fragment.recentMoveAtNanos = now - Int64(f[1])! * 1_000_000 - 123_456
            }
            XCTAssertEqual(fragment.currentRecentMovementIntensity().bitPattern, bits(f[2]), f.joined(separator: " "))
        }
    }

    // MARK: Layouts

    private func assertView<T: AView>(_ root: AView, _ id: String, _ expected: T.Type,
                                      file: StaticString = #filePath, line: UInt = #line) -> T {
        let found: AView? = root.findViewById(id)
        XCTAssertNotNil(found, "missing \(id)", file: file, line: line)
        let typed = found as? T
        XCTAssertNotNil(typed, "\(id) is \(String(describing: found.map { type(of: $0) })), expected \(T.self)",
                        file: file, line: line)
        return typed!
    }

    private func px(_ dp: Float) -> Int { return ATypedValue.toDimensionPixelSize(ATypedValue.COMPLEX_UNIT_DIP, dp) }

    private func checkCommonTree(_ root: AView) {
        XCTAssertTrue(root is AConstraintLayout)
        XCTAssertTrue(root is TripleShotOneOnOneRootLayout)
        XCTAssertEqual(root.rawLayoutDirection, AView.LAYOUT_DIRECTION_LOCALE)
        XCTAssertEqual((root.background as? AColorDrawable)?.color, argbInt(0xFF101820))
        XCTAssertEqual(root.layoutParams?.width, AViewGroup.LayoutParams.MATCH_PARENT)
        XCTAssertEqual(root.layoutParams?.height, AViewGroup.LayoutParams.MATCH_PARENT)
        let group = root as! AViewGroup
        // Child order of the XML root, plus the iOS-only exit control before the result overlay.
        let order = group.children.map { $0.viewId ?? "" }
        XCTAssertEqual(order, [R.id.oneOnOneBackground, R.id.oneOnOneCourtView, R.id.oneOnOneHudCard,
                               R.id.oneOnOneShotMeterCard, R.id.oneOnOneQuestionCard, R.id.oneOnOneControls,
                               TripleShotOneOnOneLayouts.IOS_EXIT_CONTROL_ID, R.id.oneOnOneResultOverlay])
        let background = assertView(root, R.id.oneOnOneBackground, AImageView.self)
        XCTAssertEqual(background.scaleType, AImageView.ScaleType.MATRIX)
        _ = assertView(root, R.id.oneOnOneCourtView, TripleShotCourtView.self)
        for id in [R.id.oneOnOneHumanScore, R.id.oneOnOneBotScore, R.id.oneOnOnePossession, R.id.oneOnOneStatus,
                   R.id.oneOnOneShotChanceText, R.id.oneOnOneResultTitle, R.id.oneOnOneResultScore,
                   R.id.oneOnOneQuestionTitle, R.id.oneOnOneQuestionPrompt, R.id.oneOnOneQuestionFeedback] {
            _ = assertView(root, id, ATextView.self)
        }
        for id in [R.id.oneOnOneShootButton, R.id.oneOnOneFakeButton, R.id.oneOnOneBlockButton,
                   R.id.oneOnOneJumpButton] {
            XCTAssertEqual(assertView(root, id, AButton.self).visibility, AView.GONE, id)
        }
        // android:textAllCaps="false" on every visible button of both layouts.
        for id in [R.id.oneOnOneQuestionContinue, R.id.oneOnOneQuestionExit,
                   R.id.oneOnOneQuestionAnswer1, R.id.oneOnOneQuestionAnswer2, R.id.oneOnOneQuestionAnswer3,
                   R.id.oneOnOneQuestionAnswer4, R.id.oneOnOneHomeButton, R.id.oneOnOneAgainButton] {
            XCTAssertFalse(assertView(root, id, AButton.self).isAllCaps, id)
        }
        let meter = assertView(root, R.id.oneOnOneShotMeter, AProgressBar.self)
        XCTAssertEqual(meter.progressStyle, AProgressBar.Style.HORIZONTAL)
        XCTAssertEqual(meter.max, 95)
        XCTAssertEqual(meter.progress, 0)
        XCTAssertEqual(meter.progressTintList?.defaultColor, argbInt(0xFF087E70))
        XCTAssertEqual(meter.progressBackgroundTintList?.defaultColor, argbInt(0xFFD8E5E1))
        XCTAssertEqual(assertView(root, R.id.oneOnOneShotMeterCard, ACardView.self).visibility, AView.GONE)
        let question = assertView(root, R.id.oneOnOneQuestionCard, ACardView.self)
        XCTAssertEqual(question.visibility, AView.GONE)
        XCTAssertTrue(question.isClickable)
        XCTAssertTrue(question.isFocusable)
        XCTAssertEqual(question.cardElevation, Float(10) * AResources.displayMetrics.density)
        XCTAssertEqual(assertView(root, R.id.oneOnOneControls, ACardView.self).visibility, AView.INVISIBLE)
        XCTAssertEqual(assertView(root, R.id.oneOnOneQuestionContinue, AButton.self).visibility, AView.GONE)
        let overlay = assertView(root, R.id.oneOnOneResultOverlay, AFrameLayout.self)
        XCTAssertEqual(overlay.visibility, AView.GONE)
        XCTAssertTrue(overlay.isClickable)
        XCTAssertEqual((overlay.background as? AColorDrawable)?.color, argbInt(0xB8000000))
        XCTAssertEqual(overlay.elevation, 0)
        let status = assertView(root, R.id.oneOnOneStatus, ATextView.self)
        XCTAssertEqual(status.maxLines, 2)
        XCTAssertEqual(status.text, AResources.getString(R.string.minik_swish_one_on_one_start_hint))
        XCTAssertEqual(assertView(root, R.id.oneOnOneShotChanceText, ATextView.self).text,
                       AResources.getString(R.string.minik_swish_one_on_one_shot_quality_default))
        XCTAssertEqual(assertView(root, R.id.oneOnOneQuestionPrompt, ATextView.self).rawTextDirection,
                       AView.TEXT_DIRECTION_LOCALE)
        let exit = assertView(root, TripleShotOneOnOneLayouts.IOS_EXIT_CONTROL_ID, AImageView.self)
        XCTAssertTrue(exit.isClickable)
        XCTAssertEqual(exit.contentDescription, AResources.getString(R.string.minik_swish_one_on_one_question_exit))
        XCTAssertEqual(exit.layoutParams?.width, px(44))
        XCTAssertEqual(exit.elevation, 0)
    }

    func testPortraitLayoutMatchesXml() {
        let root = TripleShotOneOnOneLayouts.buildPortrait()
        checkCommonTree(root)
        let hud = assertView(root, R.id.oneOnOneHudCard, ACardView.self)
        let hudParams = hud.layoutParams as! AConstraintLayout.LayoutParams
        XCTAssertEqual(hudParams.width, 0)
        XCTAssertEqual(hudParams.marginStart, px(8))
        XCTAssertEqual(hudParams.marginEnd, px(8))
        XCTAssertEqual(hudParams.topMargin, px(6))
        XCTAssertEqual(hudParams.topToTop, AConstraintLayout.LayoutParams.PARENT_ID)
        XCTAssertEqual(hud.radius, Float(18) * AResources.displayMetrics.density)
        XCTAssertEqual(hud.cardElevation, Float(5) * AResources.displayMetrics.density)
        XCTAssertEqual(hud.strokeWidth, px(1))
        XCTAssertEqual(hud.strokeColor, argbInt(0xD9FFFFFF))
        XCTAssertEqual(hud.cardBackgroundColor.defaultColor, argbInt(0xEFFFFDF7))
        XCTAssertEqual(assertView(root, R.id.oneOnOneHumanScore, ATextView.self).textSize,
                       Float(ATypedValue.toDimensionPixelSize(ATypedValue.COMPLEX_UNIT_SP, 15)))
        XCTAssertNil(assertView(root, R.id.oneOnOneStatus, ATextView.self).ellipsize)
        let meterCard = assertView(root, R.id.oneOnOneShotMeterCard, ACardView.self)
        let meterParams = meterCard.layoutParams as! AConstraintLayout.LayoutParams
        XCTAssertEqual(meterParams.width, px(220))
        XCTAssertEqual(meterParams.topToBottom, R.id.oneOnOneHudCard)
        XCTAssertEqual(assertView(root, R.id.oneOnOneShotMeter, AProgressBar.self).layoutParams?.height, px(8))
        // The portrait legacy round controls set textAllCaps false; the 1dp fake button keeps the Material default.
        for id in [R.id.oneOnOneShootButton, R.id.oneOnOneBlockButton, R.id.oneOnOneJumpButton] {
            let control = assertView(root, id, TripleShotButton.self)
            XCTAssertFalse(control.isAllCaps, id)
            XCTAssertEqual(control.insetTop, 0, id)
            XCTAssertEqual(control.paddingTop, px(4), id)
        }
        XCTAssertTrue(assertView(root, R.id.oneOnOneFakeButton, TripleShotButton.self).isAllCaps)
        XCTAssertEqual(assertView(root, R.id.oneOnOneJumpButton, AButton.self).buttonStyle, AButton.Style.OUTLINED)
        // Portrait answers are a vertical list of TripleShotButtons.
        for id in [R.id.oneOnOneQuestionAnswer1, R.id.oneOnOneQuestionAnswer2, R.id.oneOnOneQuestionAnswer3,
                   R.id.oneOnOneQuestionAnswer4, R.id.oneOnOneQuestionContinue, R.id.oneOnOneQuestionExit,
                   R.id.oneOnOneHomeButton, R.id.oneOnOneAgainButton] {
            _ = assertView(root, id, TripleShotButton.self)
        }
        let answer1 = assertView(root, R.id.oneOnOneQuestionAnswer1, AButton.self)
        XCTAssertEqual(answer1.buttonStyle, AButton.Style.OUTLINED)
        XCTAssertEqual(answer1.minimumHeight, px(42))
        XCTAssertEqual(answer1.cornerRadius, px(14))
        XCTAssertEqual((answer1.layoutParams as? ALinearLayout.LayoutParams)?.topMargin, px(8))
        XCTAssertEqual((assertView(root, R.id.oneOnOneQuestionAnswer2, AButton.self).layoutParams
                            as? ALinearLayout.LayoutParams)?.topMargin, px(5))
        let exitButton = assertView(root, R.id.oneOnOneQuestionExit, AButton.self)
        XCTAssertEqual(exitButton.buttonStyle, AButton.Style.TEXT)
        XCTAssertEqual(exitButton.insetTop, 0)
        XCTAssertEqual(exitButton.insetBottom, 0)
        XCTAssertEqual(exitButton.paddingLeft, px(10))
        XCTAssertEqual(exitButton.layoutParams?.height, px(36))
        let resultCard = assertView(root, R.id.oneOnOneResultTitle, ATextView.self).parentGroup!.parentGroup as! ACardView
        XCTAssertEqual((resultCard.layoutParams as? AFrameLayout.LayoutParams)?.leftMargin, px(26))
        XCTAssertEqual(resultCard.layoutParams?.width, AViewGroup.LayoutParams.MATCH_PARENT)
        XCTAssertEqual(resultCard.cardElevation, Float(12) * AResources.displayMetrics.density)
        let exitParams = assertView(root, TripleShotOneOnOneLayouts.IOS_EXIT_CONTROL_ID, AImageView.self).layoutParams
            as! AConstraintLayout.LayoutParams
        XCTAssertEqual(exitParams.topToBottom, R.id.oneOnOneHudCard)
        XCTAssertEqual(exitParams.endToEnd, AConstraintLayout.LayoutParams.PARENT_ID)
    }

    func testLandscapeLayoutMatchesXml() {
        let root = TripleShotOneOnOneLayouts.buildLandscape()
        checkCommonTree(root)
        let hud = assertView(root, R.id.oneOnOneHudCard, ACardView.self)
        XCTAssertEqual(hud.layoutParams?.width, px(440))
        XCTAssertEqual((hud.layoutParams as? AConstraintLayout.LayoutParams)?.topMargin, px(5))
        XCTAssertEqual(hud.radius, Float(16) * AResources.displayMetrics.density)
        XCTAssertEqual(hud.cardElevation, Float(4) * AResources.displayMetrics.density)
        let status = assertView(root, R.id.oneOnOneStatus, ATextView.self)
        XCTAssertEqual(status.ellipsize, ATextUtils.TruncateAt.END)
        XCTAssertEqual(status.textSize, Float(ATypedValue.toDimensionPixelSize(ATypedValue.COMPLEX_UNIT_SP, 9.5)))
        let meterCard = assertView(root, R.id.oneOnOneShotMeterCard, ACardView.self)
        let meterParams = meterCard.layoutParams as! AConstraintLayout.LayoutParams
        XCTAssertEqual(meterParams.width, px(205))
        XCTAssertEqual(meterParams.marginStart, px(8))
        XCTAssertEqual(meterParams.endToEnd, AConstraintLayout.LayoutParams.UNSET)
        XCTAssertEqual(assertView(root, R.id.oneOnOneShotMeter, AProgressBar.self).layoutParams?.height, px(7))
        let question = assertView(root, R.id.oneOnOneQuestionCard, ACardView.self)
        let questionParams = question.layoutParams as! AConstraintLayout.LayoutParams
        XCTAssertEqual(questionParams.width, px(560))
        XCTAssertEqual(questionParams.topToTop, AConstraintLayout.LayoutParams.PARENT_ID)
        XCTAssertEqual(questionParams.bottomToBottom, AConstraintLayout.LayoutParams.PARENT_ID)
        XCTAssertEqual(assertView(root, R.id.oneOnOneQuestionPrompt, ATextView.self).maxLines, 3)
        // Landscape uses plain MaterialButtons in a 2x2 grid.
        let answer1 = assertView(root, R.id.oneOnOneQuestionAnswer1, AButton.self)
        let answer2 = assertView(root, R.id.oneOnOneQuestionAnswer2, AButton.self)
        XCTAssertFalse(answer1 is TripleShotButton)
        XCTAssertTrue(answer1.parentGroup === answer2.parentGroup)
        XCTAssertEqual((answer1.layoutParams as? ALinearLayout.LayoutParams)?.weight, 1)
        XCTAssertEqual((answer1.layoutParams as? ALinearLayout.LayoutParams)?.marginEnd, px(3))
        XCTAssertEqual((answer2.layoutParams as? ALinearLayout.LayoutParams)?.marginStart, px(3))
        XCTAssertEqual(answer1.minimumHeight, px(38))
        let continueButton = assertView(root, R.id.oneOnOneQuestionContinue, AButton.self)
        let exitButton = assertView(root, R.id.oneOnOneQuestionExit, AButton.self)
        XCTAssertTrue(continueButton.parentGroup === exitButton.parentGroup)
        XCTAssertEqual(continueButton.layoutParams?.width, px(210))
        XCTAssertEqual(continueButton.layoutParams?.height, px(38))
        XCTAssertEqual(exitButton.layoutParams?.height, px(34))
        let controls = assertView(root, R.id.oneOnOneControls, ACardView.self)
        XCTAssertEqual(controls.layoutParams?.width, px(1))
        // Landscape legacy controls: plain 1dp MaterialButtons with the Material defaults (all caps).
        for id in [R.id.oneOnOneShootButton, R.id.oneOnOneFakeButton, R.id.oneOnOneBlockButton,
                   R.id.oneOnOneJumpButton] {
            let control = assertView(root, id, AButton.self)
            XCTAssertFalse(control is TripleShotButton, id)
            XCTAssertTrue(control.isAllCaps, id)
            XCTAssertEqual(control.layoutParams?.width, px(1), id)
        }
        let resultCard = assertView(root, R.id.oneOnOneResultTitle, ATextView.self).parentGroup!.parentGroup as! ACardView
        XCTAssertEqual(resultCard.layoutParams?.width, px(520))
        XCTAssertEqual((resultCard.layoutParams as? AFrameLayout.LayoutParams)?.gravity, AGravity.CENTER)
        let exitParams = assertView(root, TripleShotOneOnOneLayouts.IOS_EXIT_CONTROL_ID, AImageView.self).layoutParams
            as! AConstraintLayout.LayoutParams
        XCTAssertEqual(exitParams.topToTop, AConstraintLayout.LayoutParams.PARENT_ID)
        XCTAssertEqual(exitParams.topMargin, px(5))
    }

    /// iOS-only rule: the exit control yields to the question card and the result overlay (each has its own exit).
    func testIosExitControlYieldsToQuestionCardAndResultOverlay() {
        for root in [TripleShotOneOnOneLayouts.buildPortrait(), TripleShotOneOnOneLayouts.buildLandscape()] {
            let layout = root as! TripleShotOneOnOneRootLayout
            let exit: AView = root.findViewById(TripleShotOneOnOneLayouts.IOS_EXIT_CONTROL_ID)!
            let question: AView = root.findViewById(R.id.oneOnOneQuestionCard)!
            let overlay: AView = root.findViewById(R.id.oneOnOneResultOverlay)!
            layout.syncIosExitControl()
            XCTAssertEqual(exit.visibility, AView.VISIBLE)
            question.visibility = AView.VISIBLE
            layout.syncIosExitControl()
            XCTAssertEqual(exit.visibility, AView.INVISIBLE)
            question.visibility = AView.GONE
            layout.syncIosExitControl()
            XCTAssertEqual(exit.visibility, AView.VISIBLE)
            // Driven by real layout passes, as at run time.
            let width = AMeasureSpec.makeMeasureSpec(1170, AMeasureSpec.EXACTLY)
            let height = AMeasureSpec.makeMeasureSpec(2532, AMeasureSpec.EXACTLY)
            overlay.visibility = AView.VISIBLE
            root.measure(width, height)
            root.layout(0, 0, 1170, 2532)
            XCTAssertEqual(exit.visibility, AView.INVISIBLE)
            overlay.visibility = AView.GONE
            root.measure(width, height)
            root.layout(0, 0, 1170, 2532)
            XCTAssertEqual(exit.visibility, AView.VISIBLE)
        }
    }

